// Server-rendered explanatory content (SEO/AdSense content-depth layer) for individual
// tools served through the dynamic /tools/[slug] route. Each entry supplies the prose,
// worked example, and FAQ set that gets rendered around the interactive calculator
// component so the page is not a thin "card + launch button" shell.
//
// Pattern follows deploy/src/app/tools/gst-interest-calculator/page.tsx (the reference
// page approved 2026-07-20 — see COORDINATION-LOG.md).

export interface ToolFaq {
  question: string;
  answer: string;
}

export interface ToolContent {
  /** Short eyebrow label, e.g. "CGST Act Section 47 Compliance Engine" */
  eyebrow: string;
  /** Lede paragraph shown directly under the H1 */
  lede: string;
  /** Section 1: what the tool does / statutory basis. Array of paragraphs. */
  overviewHeading: string;
  overview: string[];
  /** Section 2: worked numeric example */
  exampleHeading: string;
  exampleIntro: string;
  exampleRows: { label: string; value: string }[];
  /** FAQs */
  faqs: ToolFaq[];
}

